    val AdvancedMesh by lazy { icon("advanced-mesh", Part(MESH_CELLS, 0.6f, true)) }

    /** The advanced mesh icon's cells: four across, three down, with thin gaps. */
    private val MESH_CELLS = buildString {
        for (row in 0 until 3) for (col in 0 until 4) {
            val x = 1.5f + col * 5.625f
            val y = 4.9f + row * 5.233f
            append("M$x ${y}h4.425v4.033h-4.425z")
        }
    }

